    "여러 도시가 공공 자전거를 확대하면서 대여 시간, 이동 경로, 반납 장소와 같은 이용 데이터도 빠르게 쌓이고 있다. 이 데이터는 시민이 실제로 어떤 길을 이용하고 어느 시간대에 이동 수요가 집중되는지를 보여 주기 때문에 교통 정책을 세우는 데 중요한 근거가 될 수 있다. 예를 들어 특정 역 주변에서 아침마다 자전거가 부족하다면 출근 수요가 높다는 뜻이고, 어떤 도로에서 반납이 적다면 그 구간이 위험하거나 접근성이 낮을 가능성이 있다. 따라서 공공 자전거 데이터는 단순히 자전거 수를 늘리는 문제를 넘어 보행로, 버스 정류장, 지하철역과 연결된 도시 이동 구조를 다시 설계하게 한다. 그러나 데이터가 많다고 해서 정책이 자동으로 정확해지는 것은 아니다. 스마트폰 사용에 익숙한 젊은 층의 이용 기록이 과도하게 반영되면 노인이나 어린이처럼 자전거를 적게 이용하는 사람들의 이동 어려움은 보이지 않을 수 있다. 또한 이동 경로가 지나치게 자세히 공개될 경우 개인의 생활 패턴이 드러날 위험도 있다. 그러므로 지방자치단체는 데이터를 활용하되 시민의 개인정보를 보호하고, 숫자로 드러나지 않는 교통 약자의 목소리도 함께 조사해야 한다. 결국 공공 자전거 데이터의 가치는 이동을 많이 기록하는 데 있는 것이 아니라, 기록되지 않은 불편까지 발견해 더 안전하고 균형 잡힌 도시를 만드는 데 있다.",
  chinese:
    "随着许多城市扩大公共自行车服务，租借时间、移动路线、归还地点等使用数据也在快速积累。这些数据能显示市民实际使用哪些道路、哪个时间段移动需求集中，因此可以成为制定交通政策的重要依据。例如，如果某个车站周边每天早上都缺少自行车，就说明通勤需求高；如果某条道路归还量少，可能说明该路段危险或可达性低。因此，公共自行车数据不只是增加自行车数量的问题，还能促使城市重新设计与步行道、公交站、地铁站相连的移动结构。然而，并不是数据越多政策就会自动越准确。如果熟悉智能手机的年轻群体的使用记录被过度反映，老人或儿童等较少使用自行车者的移动困难就可能看不见。此外，如果移动路线过于详细地公开，个人生活模式也有暴露风险。因此，地方政府应利用数据，同时保护市民个人信息，并调查数字中没有显现的交通弱势群体声音。归根结底，公共自行车数据的价值不在于记录大量移动，而在于发现未被记录的不便，建设更安全、更均衡的城市。",
