  estimatedTime: "18 分钟",
  korean:
    "원격 수업이 일상화되면서 많은 학생이 화면 앞에서 느끼는 피로를 호소하고 있다. 처음에는 접속 불안정, 음질 저하, 기기 부족과 같은 기술적 문제가 가장 큰 원인으로 지적되었다. 물론 이러한 문제는 수업 참여를 어렵게 만들고 학습 격차를 키울 수 있다. 그러나 원격 수업의 피로를 기술 문제로만 설명하기에는 부족하다. 학생은 교실에서 자연스럽게 얻던 시선, 표정, 짧은 대화와 같은 사회적 신호를 온라인 공간에서는 충분히 받기 어렵다. 또 모든 활동이 과제 제출과 출석 기록으로 남으면 학생은 쉬는 시간에도 평가받고 있다는 압박을 느낄 수 있다. 특히 집 안에 조용한 학습 공간이 없거나 가족 돌봄을 함께 해야 하는 학생에게 원격 수업은 더 큰 부담이 된다. 따라서 원격 수업을 개선하려면 장비 지원뿐만 아니라 수업 설계 자체를 바꾸어야 한다. 교사는 긴 강의를 줄이고 토론, 짧은 쓰기, 개인 피드백을 적절히 섞어 학생이 수동적으로 화면만 바라보지 않도록 해야 한다. 학교는 과제량과 접속 시간을 조정하고, 학생의 가정 환경을 고려한 상담 체계를 마련할 필요가 있다. 결국 원격 수업의 질은 기술이 얼마나 안정적인가에만 달려 있지 않다. 학생이 온라인에서도 관계를 느끼고 배움의 리듬을 유지할 수 있도록 교육 환경 전체를 세심하게 설계하는 데 달려 있다.",
  chinese:
    "随着远程课堂日常化，许多学生诉说自己在屏幕前感到疲劳。起初，连接不稳定、音质下降、设备不足等技术问题被指出为最大原因。当然，这些问题会让课堂参与变难，也可能扩大教育差距。然而，仅用技术问题解释远程课堂疲劳是不够的。学生在教室中自然获得的视线、表情、简短对话等社会信号，在网络空间中很难充分获得。此外，如果所有活动都留下作业提交和出勤记录，学生即使在休息时间也可能感到自己正在被评价。尤其是家中没有安静学习空间，或需要兼顾家庭照料的学生，远程课堂会成为更大的负担。因此，要改善远程课堂，不仅要支持设备，也要改变课堂设计本身。教师应减少长时间讲授，适当结合讨论、短写作和个人反馈，使学生不只是被动盯着屏幕。学校应调整作业量和在线时间，并建立考虑学生家庭环境的咨询体系。归根结底，远程课堂的质量并不只取决于技术是否稳定，而取决于能否细致设计整个教育环境，让学生在线上也能感到关系并维持学习节奏。",
