  chinese:
    "随着双职工家庭和一人家庭增加，越来越多人难以在工作日白天去医院。尤其是在地方小城市或外围地区，医院数量少，公共交通也早早停运，因此不少人会把轻微症状拖到变严重才治疗。为解决这一问题，一些地方政府正在以保健所或公立医院为中心运营夜间公共诊疗。夜间诊疗能提高上班族和承担照护责任居民的医疗可及性，也能减少涌向急诊室的轻症患者，因此受到积极评价。然而，并不是延长运营时间就能自动解决地区医疗空白。如果医生和护士人力不足，现有医护负担会加重；如果夜间可提供的诊疗科目有限，居民期待和实际服务之间也会出现差距。此外，如果宣传不足，真正需要的人可能不知道制度而无法使用。因此，夜间公共诊疗不应被设计成单纯把门开到更晚的政策。地方政府应调查各地区疾病需求和交通条件，并与民间医院合作调整诊疗科目和运营日期。也有必要为难以线上预约的老人或移民准备电话 안내和现场挂号。归根结底，夜间公共诊疗的价值不在于延长诊疗时间，而在于把因时间和地区原因被排除在治疗之外的居民真正带入医疗体系。",
