  level: "TOPIK II 5-6级",
  topic: "公共政策 / 科技",
  estimatedTime: "18 分钟",
  korean:
    "최근 지방자치단체와 공공기관은 예산 사용 내역, 교통량, 환경 측정 결과와 같은 공공 데이터를 시민에게 공개하는 범위를 넓히고 있다. 공공 데이터가 잘 공개되면 시민은 정책이 어떤 근거로 결정되는지 확인할 수 있고, 연구자나 기업은 그 자료를 활용해 새로운 서비스를 만들 수 있다. 또한 행정 기관은 데이터를 공개하는 과정에서 스스로 정책 효과를 점검하게 되므로 책임성이 높아진다는 장점도 있다. 그러나 데이터 공개가 곧바로 시민의 신뢰로 이어지는 것은 아니다. 자료가 너무 전문적인 형식으로 제공되거나 항목의 의미가 충분히 설명되지 않으면 시민은 공개된 자료를 이해하기 어렵다. 더구나 기관에 유리한 자료만 선택적으로 공개하고 불리한 자료는 늦게 내놓는다면, 공개 자체가 투명성의 증거가 아니라 홍보 수단으로 의심받을 수 있다. 개인정보가 포함될 가능성이 있는 자료를 충분한 검토 없이 공개하는 경우에는 시민 권리를 침해할 위험도 생긴다. 따라서 공공 데이터 정책은 공개의 양을 늘리는 데만 집중해서는 안 된다. 기관은 데이터가 어떤 방식으로 수집되었는지, 어떤 한계를 지니는지, 시민이 어떤 질문에 활용할 수 있는지를 함께 설명해야 한다. 또한 이해하기 쉬운 시각 자료와 검색 기능을 제공하고, 오류 신고나 추가 공개 요청을 받을 수 있는 절차를 마련해야 한다. 결국 공공 데이터 공개의 가치는 많은 파일을 인터넷에 올리는 데 있는 것이 아니라, 시민이 행정을 검증하고 토론에 참여할 수 있는 조건을 만드는 데 있다.",
  chinese:
    "最近，地方政府和公共机构正在扩大向市民公开预算使用明细、交通量、环境测量结果等公共数据的范围。公共数据如果公开得好，市民可以确认政策是基于什么依据决定的，研究者或企业也可以利用这些资料开发新服务。此外，行政机关在公开数据的过程中会自行检查政策效果，因此责任性也会提高。然而，数据公开并不会立刻转化为市民信任。如果资料以过于专业的形式提供，或没有充分说明项目含义，市民就难以理解公开资料。再者，如果机构只选择性公开对自己有利的资料，而延迟公开不利资料，那么公开本身可能不是透明性的证据，而会被怀疑为宣传手段。如果未经充分审查就公开可能包含个人信息的资料，也会产生侵犯市民权利的风险。因此，公共数据政策不应只关注公开数量的增加。机构应同时说明数据如何收集、具有哪些局限、市民可以用它提出什么问题。还应提供易懂的视觉资料和搜索功能，并建立错误申报或追加公开请求的程序。归根结底，公共数据公开的价值不在于把大量文件上传到网上，而在于创造让市民能够验证行政并参与讨论的条件。",
